Ladies and gentlemen, our test suite begins with a joke: a developer walks into production without tests. That's it. That's the whole joke.

Now let's make sure this checkout component doesn't flatline on the operating table.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// The bureaucracy says we need mocks. I say yes. Let's go.
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Martini Glass', price: 25.00 },
  { id: '2', name: 'Still (Medical)', price: 150.00 }
];

const renderCheckout = (cartItems = mockItems) => {
  const user = userEvent.setup();
  return {
    user,
    ...render(
      <CartProvider value={{ items: cartItems, total: 175.00, clearCart: mockClearCart }}>
        <PaymentProvider value={{ processPayment: mockProcessPayment }}>
          <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
        </PaymentProvider>
      </CartProvider>
    )
  };
};

describe('Checkout - Happy Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'MASH-4077' });
  });

  it('completes full checkout flow from shipping to confirmation', async () => {
    const { user } = renderCheckout();

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '4077 MASH Lane');
    await user.type(screen.getByLabelText(/city/i), 'Uijeongbu');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Benjamin Franklin Pierce');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/martini glass/i)).toBeInTheDocument();
    expect(screen.getByText(/\$175\.00/)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText(/MASH-4077/)).toBeInTheDocument();
    });
  });
});

describe('Checkout - Form Validation', () => {
  it('displays validation errors for empty shipping fields', async () => {
    const { user } = renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
  });

  it('validates ZIP code format', async () => {
    const { user } = renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'bad-zip');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error States', () => {
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... navigate to review, click place order
    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout([]);
    expect(screen.getByText(/your cart is empty/i)).toBeInTheDocument();
  });
});
